// Extract webhook data (CRITICAL: data is under .body)
const webhookData = $input.first().json.body;

return [{
  json: {
    alertId: webhookData.alertId,
    tenantId: $env.MS_TENANT_ID,
    clientId: $env.MS_CLIENT_ID,
    webhookPayload: webhookData
  }
}];

// Extract threat indicators for enrichment
const alert = $node['Fetch Alert Details'].json;
const indicators = {
  ips: [],
  domains: [],
  fileHashes: []
};

// Extract from evidence
if (alert.evidence) {
  for (const evidence of alert.evidence) {
    if (evidence['@odata.type'] === '#microsoft.graph.security.ipEvidence') {
      indicators.ips.push(evidence.ipAddress);
    }
    if (evidence['@odata.type'] === '#microsoft.graph.security.urlEvidence') {
      const url = new URL(evidence.url);
      indicators.domains.push(url.hostname);
    }
    if (evidence['@odata.type'] === '#microsoft.graph.security.fileEvidence') {
      if (evidence.fileDetails?.sha256) {
        indicators.fileHashes.push(evidence.fileDetails.sha256);
      }
    }
  }
}

return [{
  json: {
    alertId: alert.id,
    indicators: indicators,
    hasIndicators: indicators.ips.length > 0 || indicators.domains.length > 0 || indicators.fileHashes.length > 0
  }
}];

// Prepare LLM correlation prompt
const alert = $node['Fetch Alert Details'].json;
const similarAlerts = $input.item(0).json.similarAlerts?.value || [];
const indicators = $node['Extract Threat Indicators'].json.indicators;

const prompt = `You are a SOC analyst triaging a security alert. Analyze this alert and provide actionable intelligence.

**Current Alert:**
- ID: ${alert.id}
- Title: ${alert.title}
- Severity: ${alert.severity}
- Category: ${alert.category}
- Description: ${alert.description}
- Affected User: ${alert.assignedTo || 'N/A'}
- Detected By: ${alert.detectionSource}
- Created: ${alert.createdDateTime}

**Threat Indicators:**
- IPs: ${indicators.ips.join(', ') || 'None'}
- Domains: ${indicators.domains.join(', ') || 'None'}
- File Hashes: ${indicators.fileHashes.join(', ') || 'None'}

**Similar Alerts (Last 24h):**
Found ${similarAlerts.length} similar alerts with same severity.
${similarAlerts.slice(0, 5).map(a => `- ${a.title} (${a.category})`).join('\n')}

**Analysis Required:**
1. Calculate risk score (0-100) based on severity, indicators, and pattern
2. Determine if this is part of a larger attack campaign
3. Assess whether automated remediation is safe
4. Provide clear attack narrative
5. Recommend specific actions with priority

**Required Response Format (JSON only):**
{
  "riskScore": 0-100,
  "severity": "informational/low/medium/high/critical",
  "isDuplicate": true/false,
  "duplicateOf": "alert-id or null",
  "attackStory": "clear narrative of what happened",
  "attackType": "phishing/malware/data-exfil/credential-theft/etc",
  "priority": "p1/p2/p3/p4",
  "actions": [
    {"action": "specific action", "urgency": "immediate/high/medium/low", "automatable": true/false}
  ],
  "reasoning": "detailed analysis"
}

Respond with ONLY the JSON object.`;

return [{
  json: {
    prompt: prompt,
    alertData: alert
  }
}];

// Universal LLM response parser
const response = $input.first().json;
const alertData = $node['Prepare Correlation Prompt'].json.alertData;

function extractJSON(llmResponse) {
  let text;
  if (llmResponse.choices?.[0]?.message?.content) text = llmResponse.choices[0].message.content;
  else if (llmResponse.content?.[0]?.text) text = llmResponse.content[0].text;
  else if (llmResponse.candidates?.[0]?.content?.parts?.[0]?.text) text = llmResponse.candidates[0].content.parts[0].text;
  else if (llmResponse.response) text = llmResponse.response;
  else text = llmResponse.text || JSON.stringify(llmResponse);

  text = text.replace(/```json\n?|```\n?/g, '').trim();
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  return JSON.parse(jsonMatch ? jsonMatch[0] : text);
}

try {
  const analysis = extractJSON(response);
  return [{
    json: {
      alertId: alertData.id,
      alert: alertData,
      aiAnalysis: analysis,
      riskScore: analysis.riskScore,
      severity: analysis.severity,
      priority: analysis.priority,
      actions: analysis.actions,
      attackStory: analysis.attackStory,
      isCritical: analysis.severity === 'critical',
      timestamp: new Date().toISOString()
    }
  }];
} catch (error) {
  return [{
    json: {
      alertId: alertData.id,
      alert: alertData,
      aiAnalysis: { error: error.message },
      riskScore: 0,
      severity: 'low',
      priority: 'p4',
      actions: [{action: 'Manual review required', urgency: 'medium', automatable: false}],
      attackStory: `AI analysis failed: ${error.message}`,
      isCritical: false,
      timestamp: new Date().toISOString()
    }
  }];
}

// Execute automated remediation actions
const data = $input.first().json;
const alert = data.alert;
const actions = data.actions || [];

// Extract affected entities
const affectedUser = alert.evidence?.find(e => e['@odata.type'] === '#microsoft.graph.security.userEvidence');
const affectedDevice = alert.evidence?.find(e => e['@odata.type'] === '#microsoft.graph.security.deviceEvidence');

const remediationActions = [];

// User remediation
if (affectedUser?.userAccount?.accountName) {
  remediationActions.push({
    type: 'disable_user',
    userId: affectedUser.userAccount.accountName,
    action: 'PATCH /users/{id} {accountEnabled: false}'
  });
  remediationActions.push({
    type: 'revoke_sessions',
    userId: affectedUser.userAccount.accountName,
    action: 'POST /users/{id}/revokeSignInSessions'
  });
}

// Device remediation
if (affectedDevice?.deviceId) {
  remediationActions.push({
    type: 'isolate_device',
    deviceId: affectedDevice.deviceId,
    action: 'POST /security/machines/{id}/isolate'
  });
}

return [{
  json: {
    alertId: data.alertId,
    remediationActions: remediationActions,
    affectedUser: affectedUser?.userAccount?.accountName,
    affectedDevice: affectedDevice?.deviceId,
    timestamp: new Date().toISOString()
  }
}];

// Format incident notification
const data = $node['Parse AI Analysis'].json;
const analysis = data.aiAnalysis;
const alert = data.alert;

let message = `🚨 *Security Incident - ${data.severity.toUpperCase()}*\n\n`;
message += `*Alert:* ${alert.title}\n`;
message += `*Priority:* ${data.priority.toUpperCase()}\n`;
message += `*Risk Score:* ${data.riskScore}/100\n\n`;

message += `*Attack Story:*\n${data.attackStory}\n\n`;

if (analysis.attackType) {
  message += `*Attack Type:* ${analysis.attackType}\n\n`;
}

message += `*Recommended Actions:*\n`;
data.actions.forEach((action, i) => {
  const icon = action.automatable ? '🤖' : '👤';
  message += `${i+1}. ${icon} ${action.action} (${action.urgency})\n`;
});

if (data.isCritical) {
  message += `\n⚠️ *Automated Remediation Executed*\n`;
  message += `Critical severity detected - automated actions taken\n`;
}

message += `\nTimestamp: ${data.timestamp}`;

return [{
  json: {
    channel: '#security-incidents',
    text: message,
    severity: data.severity,
    priority: data.priority,
    blocks: [
      {
        type: 'header',
        text: {
          type: 'plain_text',
          text: `🚨 ${data.severity.toUpperCase()} Incident`,
          emoji: true
        }
      },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: message
        }
      }
    ]
  }
}];

